const topicData = JSON.parse($node['Generate Strategic Topic Ideas'].json.choices[0].message.content);
const context = $node['Analyze Business Context'].json;

// Scoring algorithm
const scoreTopics = (topics) => {
  return topics.map(topic => {
    // Calculate weighted score
    const scores = {
      trending: (topic.trending_relevance || 5) * 0.25,
      reach: (topic.potential_reach || 5) * 0.20,
      competition: (11 - (topic.competition_level || 5)) * 0.15, // Lower competition = higher score
      priority: (topic.publication_priority || 5) * 0.20,
      effort: topic.estimated_effort === 'low' ? 10 : topic.estimated_effort === 'medium' ? 7 : 4,
      effortWeight: 0.10,
      business: topic.business_value ? 8 : 5,
      businessWeight: 0.10
    };

    const totalScore = 
      scores.trending + 
      scores.reach + 
      scores.competition + 
      scores.priority + 
      (scores.effort * scores.effortWeight) + 
      (scores.business * scores.businessWeight);

    return {
      ...topic,
      composite_score: Math.round(totalScore * 10) / 10,
      score_breakdown: {
        trending_score: scores.trending,
        reach_score: scores.reach,
        competition_score: scores.competition,
        priority_score: scores.priority,
        effort_score: scores.effort * scores.effortWeight,
        business_score: scores.business * scores.businessWeight
      }
    };
  }).sort((a, b) => b.composite_score - a.composite_score);
};

const scoredTopics = scoreTopics(topicData);

// Categorize by priority
const categorized = {
  high_priority: scoredTopics.filter(t => t.composite_score >= 8),
  medium_priority: scoredTopics.filter(t => t.composite_score >= 6 && t.composite_score < 8),
  low_priority: scoredTopics.filter(t => t.composite_score < 6),
  quick_wins: scoredTopics.filter(t => t.estimated_effort === 'low' && t.composite_score >= 7),
  evergreen: scoredTopics.filter(t => t.trending_relevance <= 6 && t.potential_reach >= 7)
};

return {
  request_id: context.request_id,
  total_topics: scoredTopics.length,
  all_topics: scoredTopics,
  categorized_topics: categorized,
  recommendations: {
    start_with: categorized.quick_wins.slice(0, 3).map(t => t.topic_title),
    high_impact: categorized.high_priority.slice(0, 5).map(t => t.topic_title),
    content_calendar_mix: {
      weekly_high_priority: 2,
      weekly_medium_priority: 3,
      weekly_quick_wins: 2,
      monthly_evergreen: 4
    }
  },
  analysis_summary: {
    avg_score: Math.round((scoredTopics.reduce((sum, t) => sum + t.composite_score, 0) / scoredTopics.length) * 10) / 10,
    high_scoring_count: categorized.high_priority.length,
    quick_win_count: categorized.quick_wins.length,
    top_content_pillars: [...new Set(scoredTopics.slice(0, 10).map(t => t.content_pillar))]
  },
  generated_at: new Date().toISOString()
};

const topicData = $node['Score & Prioritize Topics'].json;
const recommendations = topicData.recommendations;

// Generate 4-week content calendar
const calendar = [];
const startDate = new Date();
const topics = topicData.all_topics;

let topicIndex = 0;
for (let week = 0; week < 4; week++) {
  const weekStart = new Date(startDate);
  weekStart.setDate(startDate.getDate() + (week * 7));

  const weekTopics = [];

  // Add high priority topics (2 per week)
  for (let i = 0; i < 2 && topicIndex < topics.length; i++) {
    if (topics[topicIndex].composite_score >= 8) {
      weekTopics.push({
        ...topics[topicIndex],
        scheduled_date: new Date(weekStart.getTime() + (i * 2 * 24 * 60 * 60 * 1000)).toISOString().split('T')[0],
        calendar_type: 'high_priority'
      });
      topicIndex++;
    }
  }

  // Add medium priority topics (3 per week)
  for (let i = 0; i < 3 && topicIndex < topics.length; i++) {
    if (topics[topicIndex].composite_score >= 6 && topics[topicIndex].composite_score < 8) {
      weekTopics.push({
        ...topics[topicIndex],
        scheduled_date: new Date(weekStart.getTime() + ((i + 2) * 24 * 60 * 60 * 1000)).toISOString().split('T')[0],
        calendar_type: 'medium_priority'
      });
      topicIndex++;
    }
  }

  // Add quick wins (2 per week)
  const quickWins = topics.filter(t => t.estimated_effort === 'low' && t.composite_score >= 7);
  for (let i = 0; i < 2 && i < quickWins.length; i++) {
    weekTopics.push({
      ...quickWins[i],
      scheduled_date: new Date(weekStart.getTime() + ((i + 5) * 24 * 60 * 60 * 1000)).toISOString().split('T')[0],
      calendar_type: 'quick_win'
    });
  }

  calendar.push({
    week_number: week + 1,
    week_start: weekStart.toISOString().split('T')[0],
    week_end: new Date(weekStart.getTime() + (6 * 24 * 60 * 60 * 1000)).toISOString().split('T')[0],
    topics: weekTopics,
    week_theme: weekTopics.length > 0 ? weekTopics[0].content_pillar : 'Mixed content'
  });
}

return {
  request_id: topicData.request_id,
  calendar_period: '4_weeks',
  content_calendar: calendar,
  calendar_summary: {
    total_planned_content: calendar.reduce((sum, week) => sum + week.topics.length, 0),
    weekly_average: Math.round(calendar.reduce((sum, week) => sum + week.topics.length, 0) / 4),
    content_distribution: {
      high_priority: calendar.reduce((sum, week) => sum + week.topics.filter(t => t.calendar_type === 'high_priority').length, 0),
      medium_priority: calendar.reduce((sum, week) => sum + week.topics.filter(t => t.calendar_type === 'medium_priority').length, 0),
      quick_wins: calendar.reduce((sum, week) => sum + week.topics.filter(t => t.calendar_type === 'quick_win').length, 0)
    }
  },
  next_steps: [
    'Review and approve topic priorities',
    'Assign topics to research agent',
    'Begin content production pipeline',
    'Set up content calendar tracking'
  ]
};

const enhancedTopic = JSON.parse($node['Validate & Enhance Manual Topic'].json.choices[0].message.content);
const originalRequest = $node['Manual Topic Submission'].json;

// Format as single high-priority topic
const fastTrackTopic = {
  ...enhancedTopic,
  submission_type: 'manual',
  submitted_by: originalRequest.submitted_by,
  original_request: originalRequest,
  fast_track: true,
  priority_override: true,
  composite_score: 9.5, // High score for manual submissions
  calendar_type: 'fast_track'
};

return {
  request_id: `manual_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
  fast_track_topic: fastTrackTopic,
  next_action: 'immediate_research',
  bypass_calendar: true
};
